<script setup lang="ts">import{reactive,ref}from'vue';import{Eye,EyeOff}from'lucide-vue-next';import{useRoute,useRouter}from'vue-router';import{useAuthStore}from'../../store/auth';import{APIError}from'../../api/client';import AuthShell from'../../components/AuthShell.vue';const form=reactive({email:'',password:''}),error=ref(''),show=ref(false),auth=useAuthStore(),router=useRouter(),route=useRoute();async function submit(){error.value='';try{await auth.login(form.email,form.password);await router.replace(String(route.query.redirect||'/'))}catch(e){error.value=e instanceof APIError?e.message:'登录失败，请稍后重试'}}</script>
<template><AuthShell><section class="auth-card panel"><h1>登录控制台</h1><p class="muted">登录后将根据账号角色进入对应工作台。</p><form @submit.prevent="submit"><label>邮箱<input v-model="form.email" type="email" autocomplete="email" required/></label><label>密码<div class="row"><input v-model="form.password" :type="show?'text':'password'" autocomplete="current-password" required/><button type="button" class="icon-button" :aria-label="show?'隐藏密码':'显示密码'" @click="show=!show"><EyeOff v-if="show" :size="18"/><Eye v-else :size="18"/></button></div></label><p v-if="error" class="error">{{error}}</p><button class="button primary wide" :disabled="auth.loading">{{auth.loading?'登录中…':'登录'}}</button></form><div class="actions"><RouterLink to="/register">注册学生/导师</RouterLink><RouterLink to="/recovery">忘记密码</RouterLink><RouterLink to="/teacher/activate">老师激活</RouterLink></div></section></AuthShell></template>
